// BUBBLE BOBBLE — Taito 1986, as data. 256x224: HUD row 0, field rows 1..13,
// 16px cells. 100 levels = 10 themes x 10 levels, generated by a seeded hash
// (zero Math.random): platforms, water, spawn spots, door. NO LADDERS — the
// arcade has none: every platform row sits exactly a jump above a reachable
// row, and each span meets the one below within two columns, so the whole
// cave is climbable by two-row jumps through the one-way platforms. The audit
// in scripts/bobcheck.mjs re-walks every level with the SAME jump rules the
// sim obeys, so an unreachable platform is a build failure, not a surprise.

export const CELL = 16
export const COLS = 16
export const ROWS = 14          // row 0 = HUD band, rows 1..13 field
export const W = 256
export const H = 224
export const FIELD_Y0 = 16      // y of row 1 top
export const FLOOR_ROW = 13

export const THEMES = [
    { name: 'PRECIPICE', sky: ['#0b1030', '#050718'], plat: '#c8763c', platLite: '#e8a86c', platDark: '#7c421e', deco: '#ffd9a0' },
    { name: 'CAVE', sky: ['#120b2e', '#050312'], plat: '#6a7fd4', platLite: '#9db1ef', platDark: '#3a4a94', deco: '#b9c8ff' },
    { name: 'GRAVEYARD', sky: ['#0a1d1a', '#03100e'], plat: '#5ea87a', platLite: '#8fd8a8', platDark: '#2e6a48', deco: '#d8ffd0' },
    { name: 'SEA FLOOR', sky: ['#08142e', '#020814'], plat: '#3f8fc8', platLite: '#7cc4ee', platDark: '#1e5a8a', deco: '#bfe8ff', water: true },
    { name: 'RUINS', sky: ['#1d1208', '#0e0803'], plat: '#b08a4a', platLite: '#e0c084', platDark: '#7a5c28', deco: '#ffe8b8' },
    { name: 'CLOUD TOP', sky: ['#18305a', '#0a1830'], plat: '#d0dcf2', platLite: '#ffffff', platDark: '#8c9cc0', deco: '#eaf2ff', water: true },
    { name: 'ICEBERG', sky: ['#0c2438', '#04101c'], plat: '#7cc8e0', platLite: '#c8f0ff', platDark: '#40788f', deco: '#e8fbff', water: true },
    { name: 'VOLCANO', sky: ['#2a0c08', '#120403'], plat: '#c05038', platLite: '#f08860', platDark: '#802818', deco: '#ffd090' },
    { name: 'CAVERN', sky: ['#160b24', '#0a0412'], plat: '#9a5ac0', platLite: '#c890e8', platDark: '#66308a', deco: '#ecc8ff' },
    { name: 'MOONLIGHT', sky: ['#101a34', '#060a18'], plat: '#8090b8', platLite: '#b8c8e8', platDark: '#505c80', deco: '#dce6ff' },
]

export function themeOf(level) { return THEMES[Math.floor(level / 10) % THEMES.length] }
export const isBossLevel = (level) => (level + 1) % 20 === 0

// deterministic per-level hash
export function lhash(level, salt) {
    let h = (level * 2654435761 + salt * 40503) >>> 0
    h = ((h ^ (h >>> 15)) * 2246822519) >>> 0
    h = ((h ^ (h >>> 13)) * 3266489917) >>> 0
    return (h ^ (h >>> 16)) >>> 0
}

// A level is: rows of platform spans + optional water. Jump budget the
// generator must respect (and the audit re-checks): apex 38px = 2 rows up,
// mid-air reach ~2 cols across. No ladders: the rows are exactly 2 apart and
// each span overlaps the one below within 2 columns, so floor->apex is a jump
// chain by construction.
export function genLevel(level) {
    if (level === 0) return caveOne()
    const h = (salt) => lhash(level + 1, salt)
    const t = themeOf(level)
    const water = !!t.water
    const platforms = []   // {row, c0, c1} top surfaces the player lands on
    // 3..4 floating rows, the bottom one a jump above the floor (11 or 12:
    // the jump apex is 2 rows, so row 10 would already be out of reach)
    const rowCount = 3 + (h(1) % 2)
    const bottomRow = 11 + (h(2) % 2)
    const rowsUsed = []
    for (let i = 0; i < rowCount; i++) rowsUsed.push(bottomRow - 2 * i)
    rowsUsed.reverse()                       // top-first
    // build the spans bottom-up so each one has to meet the row below it
    let prevC0 = 0, prevC1 = COLS - 1
    const spans = []
    for (let i = rowsUsed.length - 1; i >= 0; i--) {
        const row = rowsUsed[i]
        const wide = 6 + (h(10 + i) % 5)
        const c0min = Math.max(1, prevC0 - 2 - wide)
        const c0max = Math.min(prevC1 + 2, COLS - 2 - wide)
        const c0 = c0min + (h(20 + i) % Math.max(1, c0max - c0min + 1))
        spans.push({ row, c0, c1: c0 + wide })
        prevC0 = c0; prevC1 = c0 + wide
    }
    for (let i = spans.length - 1; i >= 0; i--) platforms.push(spans[i])

    // spawns: enemies on platform tops + floor, deterministic
    const spawns = []
    const roster = 6 + Math.floor(level / 12)
    const kinds = isBossLevel(level) ? ['boss'] : []
    const pool = ['zenchan', 'zenchan', 'pulppul', 'tongling', 'zenchan', 'pulppul']
    while (kinds.length < roster) kinds.push(pool[h(60 + kinds.length) % pool.length])
    // spread walker spawns across their span so two riders never stack on one
    // column (a stacked pair is a meat wall the attract demo can't answer)
    const used = new Map()
    // two floor-walkers per level keep the ground alive and feed the water
    // rule on wet themes (they spawn in the shallows and emerge as snails)
    const surf = platforms.concat([{ row: FLOOR_ROW, c0: 0, c1: COLS - 1 }, { row: FLOOR_ROW, c0: 0, c1: COLS - 1 }])
    for (const k of kinds) {
        if (k === 'boss') { spawns.push({ kind: k, col: COLS / 2 | 0, row: 3 }); continue }
        const s = k === 'pulppul' ? { col: 1 + h(70 + spawns.length) % (COLS - 2), row: 4 + h(80 + spawns.length) % 7 }
            : surf[h(90 + spawns.length) % surf.length]
        let col
        if (s.c0 !== undefined) {
            const width = s.c1 - s.c0 + 1
            const n = used.get(`${s.row},${s.c0},${s.c1}`) || 0
            used.set(`${s.row},${s.c0},${s.c1}`, n + 1)
            col = s.c0 + Math.min(width - 1, (h(100 + spawns.length) + n * Math.ceil(width / 3)) % width)
        } else col = s.col
        spawns.push({ kind: k, col, row: s.row })
    }

    // entry column near the top-left, door top-right-ish, on/above real ground
    const entry = { col: 1 + h(110) % 3, row: 2 }
    const door = { col: COLS - 2 - h(120) % 3, row: (surf[0] ? surf[0].row : 5) }
    if (door.col < surf[0]?.c0 || door.col > surf[0]?.c1) { door.col = surf[0] ? surf[0].c0 + h(130) % (surf[0].c1 - surf[0].c0 + 1) : 8 }

    return {
        number: level + 1,
        name: `${t.name} ${String(level % 10 + 1).padStart(2, '0')}`,
        theme: t,
        water,
        platforms,
        spawns,
        entry,
        door,
        roster: kinds.length,
        blubbaAt: Math.max(2400, 5400 - level * 30), // linger too long and HE arrives
    }
}

// Cave 1 — the arcade's round-1 cave, by hand: an open box, a central spine
// with paired side ledges, door on the top shelf, Zen-chans on every tier.
// Every tier is a two-row jump from the one below (the audit re-proves it).
function caveOne() {
    const t = themeOf(0)
    const platforms = [
        { row: 3, c0: 5, c1: 10 },
        { row: 5, c0: 1, c1: 5 },
        { row: 5, c0: 10, c1: 14 },
        { row: 7, c0: 5, c1: 10 },
        { row: 9, c0: 1, c1: 5 },
        { row: 9, c0: 10, c1: 14 },
        { row: 11, c0: 5, c1: 10 },
    ]
    const spawns = [
        { kind: 'zenchan', col: 6, row: 11 },
        { kind: 'zenchan', col: 9, row: 11 },
        { kind: 'zenchan', col: 3, row: 9 },
        { kind: 'zenchan', col: 12, row: 9 },
        { kind: 'zenchan', col: 7, row: 7 },
        { kind: 'zenchan', col: 3, row: FLOOR_ROW },
        { kind: 'zenchan', col: 12, row: FLOOR_ROW },
    ]
    return {
        number: 1,
        name: `${t.name} 01`,
        theme: t,
        water: false,
        platforms,
        spawns,
        entry: { col: 1, row: 2 },
        door: { col: 8, row: 3 },
        roster: spawns.length,
        blubbaAt: 5400, // linger too long and HE arrives
    }
}

export const LEVEL_COUNT = 100

// chain pay when a trapped enemy pops (1st, 2nd, ... on this screen)
export const CHAIN_PAY = [100, 200, 300, 400, 500, 1000, 2000, 3000, 4000, 5000, 6000, 8000, 10000]
export const chainPay = (chainIndex) => CHAIN_PAY[Math.min(CHAIN_PAY.length - 1, chainIndex)]
// fruit values by kind index
export const FRUITS = ['apple', 'orange', 'grapes', 'bannana', 'pear', 'melon', 'cake', 'cookie', 'milk', 'candy']
export const FRUIT_POINTS = [300, 400, 500, 600, 700, 800, 1000, 2000, 3000, 5000]
export const LETTERS = ['E', 'X', 'T', 'E', 'N', 'D']
// chain >= 4 drops a transform instead of fruit
export const POWERS = { 4: 'red', 5: 'cyan', 6: 'green', 7: 'pink' }
export const POWER_TICKS = 600
export const BOSS_POINTS = 5000
export const LEVEL_BONUS = (level) => 200 * (level + 1)
